////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
// Velocities and forces. The turning ones use the sense of TurnEntity (a positive yaw turns left), which is the other way round
// about y than the right hand rule of the library, so y changes its sign; velocities are in degrees per second.
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
void bb_physics_linear_velocity(int32_t entity, float x, float y, float z, int32_t global)
{
	body_rec& r = body_of(entity, "PhysicsLinearVelocity");
	world_rec& w = world_of(r.world, "PhysicsLinearVelocity");
	physics::api const& l = lib("PhysicsLinearVelocity");
	float linear[3] = { x, y, z }, current[3], angular[3];
	to_world(entity, global != 0, linear);
	l.sim_body_get_velocity(w.sim, r.body, current, angular);
	l.sim_body_set_velocity(w.sim, r.body, linear, angular);
}

void bb_physics_angular_velocity(int32_t entity, float x, float y, float z, int32_t global)
{
	body_rec& r = body_of(entity, "PhysicsAngularVelocity");
	world_rec& w = world_of(r.world, "PhysicsAngularVelocity");
	physics::api const& l = lib("PhysicsAngularVelocity");
	float angular[3] = { x * deg_to_rad, -y * deg_to_rad, z * deg_to_rad }, linear[3], current[3];
	to_world(entity, global != 0, angular);
	l.sim_body_get_velocity(w.sim, r.body, linear, current);
	l.sim_body_set_velocity(w.sim, r.body, linear, angular);
}

static float velocity_axis(int32_t entity, int axis, bool angular, int32_t global, const char* what)
{
	body_rec& r = body_of(entity, what);
	world_rec& w = world_of(r.world, what);
	float linear[3], spin[3];
	lib(what).sim_body_get_velocity(w.sim, r.body, linear, spin);
	if (!angular) {
		from_world(entity, global != 0, linear);
		return linear[axis];
	}
	from_world(entity, global != 0, spin);
	return (axis == 1 ? -spin[1] : spin[axis]) * rad_to_deg;
}
float bb_get_physics_linear_velocity_x(int32_t e, int32_t g) { return velocity_axis(e, 0, false, g, "GetPhysicsLinearVelocityX"); }
float bb_get_physics_linear_velocity_y(int32_t e, int32_t g) { return velocity_axis(e, 1, false, g, "GetPhysicsLinearVelocityY"); }
float bb_get_physics_linear_velocity_z(int32_t e, int32_t g) { return velocity_axis(e, 2, false, g, "GetPhysicsLinearVelocityZ"); }
float bb_get_physics_angular_velocity_x(int32_t e, int32_t g) { return velocity_axis(e, 0, true, g, "GetPhysicsAngularVelocityX"); }
float bb_get_physics_angular_velocity_y(int32_t e, int32_t g) { return velocity_axis(e, 1, true, g, "GetPhysicsAngularVelocityY"); }
float bb_get_physics_angular_velocity_z(int32_t e, int32_t g) { return velocity_axis(e, 2, true, g, "GetPhysicsAngularVelocityZ"); }

// A force or torque stays for every step of the next PhysicsUpdate; an impulse is given at once.
static void apply(int32_t entity, int kind, float x, float y, float z, bool at, float px, float py, float pz, int32_t global, const char* what)
{
	body_rec& r = body_of(entity, what);
	world_rec& w = world_of(r.world, what);
	physics::api const& l = lib(what);
	if (r.desc.motion != BP_DYNAMIC) {
		die(what, "only a dynamic body takes forces and impulses.");
	}
	float v[3] = { x, y, z }, p[3] = { px, py, pz };
	if (kind == 2 || kind == 5) {
		v[1] = -v[1]; // Torque and turning impulse in the sense of TurnEntity.
	}
	to_world(entity, global != 0, v);
	if (at) {
		// The point is in the space of the body, or in the world.
		if (!global) {
			float pos[3], q[4], rm[9];
			world_pose(entity, pos, q, nullptr);
			matrix_from_quat(q, rm);
			float world_p[3];
			for (int row = 0; row < 3; row++) {
				world_p[row] = pos[row] + rm[0 + row] * p[0] + rm[3 + row] * p[1] + rm[6 + row] * p[2];
			}
			memcpy(p, world_p, sizeof(p));
		}
	}
	switch (kind) {
	case 0:
	case 1:
	case 2: {
		pending_force f = { entity, kind, { v[0], v[1], v[2] }, { p[0], p[1], p[2] } };
		w.forces.push_back(f);
		break;
	}
	case 3:
	case 4:
		l.sim_body_add_impulse(w.sim, r.body, v, at ? p : nullptr);
		break;
	case 5:
		l.sim_body_add_angular_impulse(w.sim, r.body, v);
		break;
	}
}
void bb_physics_apply_force(int32_t e, float x, float y, float z, int32_t g) { apply(e, 0, x, y, z, false, 0, 0, 0, g, "PhysicsApplyForce"); }
void bb_physics_apply_force_at(int32_t e, float x, float y, float z, float px, float py, float pz, int32_t g) { apply(e, 1, x, y, z, true, px, py, pz, g, "PhysicsApplyForceAt"); }
void bb_physics_apply_torque(int32_t e, float x, float y, float z, int32_t g) { apply(e, 2, x, y, z, false, 0, 0, 0, g, "PhysicsApplyTorque"); }
void bb_physics_apply_impulse(int32_t e, float x, float y, float z, int32_t g) { apply(e, 3, x, y, z, false, 0, 0, 0, g, "PhysicsApplyImpulse"); }
void bb_physics_apply_impulse_at(int32_t e, float x, float y, float z, float px, float py, float pz, int32_t g) { apply(e, 4, x, y, z, true, px, py, pz, g, "PhysicsApplyImpulseAt"); }
void bb_physics_apply_angular_impulse(int32_t e, float x, float y, float z, int32_t g) { apply(e, 5, x, y, z, false, 0, 0, 0, g, "PhysicsApplyAngularImpulse"); }

////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
// The world: gravity, time step and solver
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
void bb_physics_gravity(float x, float y, float z, int32_t world)
{
	float g[3] = { x, y, z };
	lib("PhysicsGravity").sim_set_gravity(world_of(world, "PhysicsGravity").sim, g);
}
static float gravity_axis(int axis, int32_t world, const char* what)
{
	float g[3];
	lib(what).sim_get_gravity(world_of(world, what).sim, g);
	return g[axis];
}
float bb_get_physics_gravity_x(int32_t world) { return gravity_axis(0, world, "GetPhysicsGravityX"); }
float bb_get_physics_gravity_y(int32_t world) { return gravity_axis(1, world, "GetPhysicsGravityY"); }
float bb_get_physics_gravity_z(int32_t world) { return gravity_axis(2, world, "GetPhysicsGravityZ"); }

